// Telegram responde {ok:false, error_code, description} cuando algo falla.
// Algunos errores son inofensivos y no merecen una alerta.
const HARMLESS = [
  'message is not modified',        // se quitaron botones que ya no estaban
  'query is too old',               // el empleado tocó un botón hace mucho
  'message to edit not found',
  "message can't be edited",
  'bot was blocked by the user',    // el empleado bloqueó el bot: no hay a quién responder
];
const actions = $('Recibir acciones').all();
const problems = [];
$input.all().forEach((item, i) => {
  const r = item.json;
  if (r.ok === true) return;
  const text = String(r.description || r.error?.message || 'sin respuesta de Telegram');
  if (HARMLESS.some(h => text.toLowerCase().includes(h))) return;
  problems.push(`${actions[i]?.json.method}: ${r.error_code || ''} ${text}`.trim());
});
if (problems.length) {
  throw new Error('Telegram rechazó acciones: ' + problems.join(' | '));  // → CM-99
}
return $input.all();
